module guide.types

// DeluluLang has two ways to declare a type, and the second one is the one every
// program needs first.
// A RECORD groups fields. Braces, `name: Type`, comma-separated.
type Point {
    x: Float,
    y: Float,
}

// A SUM lists alternatives. `=` and `|`, NOT braces — this is the shape most
// newcomers guess wrong. A variant may carry data or carry nothing.
type Shape = Circle(Float) | Rect(Float, Float) | Empty

// Sums are recursive, which is what makes trees, lists, and syntax nodes possible.
type Tree = Leaf | Node(Tree, Int, Tree)

// `match` takes a sum apart. The checker proves the match is exhaustive: leave a
// variant out and you get DL0407 before the program ever runs.
fn area(s: Shape) -> Float {
    match s {
        Circle(r) => 3.14159 * r * r
        Rect(w, h) => w * h
        Empty => 0.0
    }
}

fn insert(t: Tree, x: Int) -> Tree {
    match t {
        Leaf => Node(Leaf, x, Leaf)
        Node(l, v, r) => if x < v { Node(insert(l, x), v, r) } else { Node(l, v, insert(r, x)) }
    }
}

fn size(t: Tree) -> Int {
    match t {
        Leaf => 0
        Node(l, v, r) => 1 + size(l) + size(r)
    }
}

fn main(root: Root) ! {Write} {
    let out = root.console()
    out.println("area  = " + str(area(Rect(3.0, 4.0))))
    let t = insert(insert(insert(Leaf, 5), 2), 8)
    out.println("size  = " + str(size(t)))
    let p = Point { x: 1.5, y: 2.5 }
    out.println("point = " + str(p.x) + ", " + str(p.y))
}

module guide.lists

// Lists are indexed with `get`, and `get` is TOTAL: it returns `Option[T]`, never a
// crash and never a silent wrong answer. There is no way to index a list unsafely,
// so the "index out of bounds" class of bug does not exist here.
// The standard shape: match the Option and decide what absence means.
fn at_or(xs: List[Int], i: Int, fallback: Int) -> Int {
    match xs.get(i) {
        Some(v) => v
        None => fallback
    }
}

fn sum(xs: List[Int]) -> Int {
    var total = 0
    var i = 0
    while i < xs.len() {
        total = total + at_or(xs, i, 0)
        i = i + 1
    }
    total
}

fn largest(xs: List[Int]) -> Option[Int] {
    if xs.len() == 0 {
        None
    } else {
        var best = at_or(xs, 0, 0)
        var i = 1
        while i < xs.len() {
            let v = at_or(xs, i, best)
            if v > best {
                best = v
            } else {
                best = best
            }
            i = i + 1
        }
        Some(best)
    }
}

// `push` MUTATES the list in place and yields `Unit` — it is a statement, not an
// expression. Note the binding is `let`, not `var`: the list cell is what changes,
// not which list the name refers to. A `var` list is `val` (immutable, shareable)
// and pushing to it is DL1603.
// There is no `()` unit literal, so an "else do nothing" branch is written by
// leaving the `else` off entirely: an `if` with no `else` is a statement.
fn evens_up_to(n: Int) -> List[Int] {
    let out = []
    var i = 0
    while i <= n {
        if i % 2 == 0 { out.push(i) }
        i = i + 1
    }
    out
}

fn main(root: Root) ! {Write} {
    let out = root.console()
    // Reference capabilities (Stage 7). A plain `let xs = [...]` is `ref`: mutable and
    // local to this frame. A parameter declared without a prefix is `val`: immutable and
    // freely shareable. Passing `ref` where `val` is wanted is DL1603 — so a list you only
    // ever read is declared `val`, which is also what lets it cross to another actor
    // safely. The other direction works too: declare the parameter `ref List[Int]` when
    // the function is meant to receive a mutable list.
    let xs: val List[Int] = [5, 3, 9, 1, 7]
    out.println("sum     = " + str(sum(xs)))
    out.println("evens   = " + str(evens_up_to(10).len()))
    match largest(xs) {
        Some(m) => out.println("largest = " + str(m))
        None => out.println("largest = (empty list)")
    }
    // Out of range is not an error — it is `None`, and you decide what it means.
    out.println("xs[99]  = " + str(at_or(xs, 99, -1)))
}

module guide.errors

// DeluluLang has no exceptions. A function that can fail says so in its return type,
// and the caller must deal with it. There is no invisible control flow, which is what
// keeps the effect row an honest summary of what a call can do.
//
// `Result[T, E]` is the shape; `Ok(v)` and `Err(e)` are its two variants. The error
// type is an ordinary sum, so a caller can `match` on WHY something failed instead of
// picking apart a message string.
type ParseErr = Empty | NotANumber(Str)

// Named `to_int`, not `parse_int`: `parse_int` is a prelude builtin, and redefining a
// builtin is DL0302 — calls would resolve to the builtin and never to your function.
//
// It also shows the common conversion. The builtin answers `Option[Int]` — "a number
// or not" — and this wraps that into a `Result` that says which failure happened.
fn to_int(s: Str) -> Result[Int, ParseErr] {
    if s.len() == 0 {
        Err(Empty)
    } else {
        match parse_int(s) {
            Some(n) => Ok(n)
            None => Err(NotANumber(s))
        }
    }
}

fn describe(s: Str) -> Str {
    match to_int(s) {
        Ok(n) => "parsed " + str(n)
        Err(e) => match e { Empty => "empty input", NotANumber(bad) => "not a number: " + bad }
    }
}

// `?` propagates an `Err` to the caller unchanged. It works only where the error types
// already line up — there is no implicit conversion, because a silent error conversion
// is exactly the kind of invisible behaviour this language refuses.
//
// Note the error type: filesystem calls fail with `IoErr`, network calls fail with
// `NetErr`. Different sums, different variants, and `?` will not bridge them for you.
fn read_two(fs: Cap[FsRead]) -> Result[Str, IoErr] ! {Read} {
    let a = fs.read_text("a.txt")?
    let b = fs.read_text("b.txt")?
    Ok(a + b)
}

fn main(root: Root) ! {Write} {
    let out = root.console()
    out.println(describe("407"))
    out.println(describe(""))
    out.println(describe("40x"))
}

module guide.effects

// The row `! {…}` after a signature is the function's promise about what it may do.
// Omit it and the function is PURE — it may perform no effect at all, and the compiler
// proves it rather than trusting a comment.
// No row. This function cannot read a file, reach the network, or tell the time.
fn normalize(name: Str) -> Str {
    name.trim()
}

// A row of exactly what it does. The `Cap[Console]` parameter is the permission;
// the row is the disclosure. You need both: a capability you never declared is
// unusable, and a row you cannot back with a capability is a lie the checker catches.
fn greet(out: Cap[Console], name: Str) ! {Write} {
    out.println("hello, " + normalize(name))
}

// Effects accumulate up the call graph. `banner` performs no effect of its own, but it
// calls `greet`, so it must declare `Write` too. Every caller inherits, all the way to
// `main` — which is why `delulu authority` can compute the whole program's authority.
fn banner(out: Cap[Console]) ! {Write} {
    greet(out, "world")
    greet(out, "delulu")
}

// ROW POLYMORPHISM. `e` is a row variable: `apply` has EXACTLY the row of the function
// it is handed — no more, no less. A pure callback keeps `apply` pure; an effectful one
// makes it effectful. Without this, every higher-order function would have to assume the
// worst and the whole system would be unusable.
fn apply[T, U, e](f: fn(T) -> U ! e, x: T) -> U ! e {
    f(x)
}

fn double(n: Int) -> Int {
    n * 2
}

// `apply(double, 21)` is pure, so this function needs no row at all.
fn pure_use() -> Int {
    apply(double, 21)
}

fn main(root: Root) ! {Write} {
    let out = root.console()
    banner(out)
    out.println("apply = " + str(pure_use()))
}

module guide.capabilities

// The part newcomers guess wrong most often: an EFFECT and a RESOURCE KIND are two
// different vocabularies, and they do not share names.
//
//   `Net` is an EFFECT       — it goes in the row:  ! {Net}
//   `Http` is a RESOURCE KIND — it goes in the type: Cap[Http]
//
// Writing `Cap[Net]` is DL0307. The split is deliberate (constitution invariant 6):
// the row proves what KIND of thing a function can do and is checked at compile time;
// the capability's scope decides WHICH file or host and is checked when it runs.
// Nothing here claims a compile-time guarantee about a specific path or hostname,
// because the language cannot prove one without dependent types — and saying so
// would be a claim it refuses to make.
// Reading: effect `Read`, resource kind `FsRead`.
// (Named `read_config`, not `load`: `load` is a prelude builtin — see 03_errors.)
fn read_config(reader: Cap[FsRead], path: Str) -> Result[Str, IoErr] ! {Read} {
    reader.read_text(path)
}

// Writing: effect `Write`, resource kind `FsWrite`.
fn save(writer: Cap[FsWrite], path: Str, body: Str) -> Result[Unit, IoErr] ! {Write} {
    writer.write_text(path, body)
}

// Network: effect `Net`, resource kind `Http`. Note the error type: filesystem calls
// fail with `IoErr`, network calls fail with `NetErr`. They are different sums with
// different variants, and `?` will not silently bridge them.
fn fetch(client: Cap[Http], url: Str) -> Result[Str, NetErr] ! {Net} {
    client.get(url)
}

// A secret has no string form and no equality. Both ways of getting information out
// carry the `Declassify` effect, so "this function can reveal something about a secret"
// is visible in its type: `expose` yields the whole value and also needs
// Cap[Declassify]; `verify` yields one bit, constant-time, and is the comparison you
// usually want. `verify` carries the effect too — the bit it returns is derived from the
// secret, so hiding it would make the row a lie (campaign finding P17-IF1).
fn password_matches(held: Secret[Str], attempt: Secret[Str]) -> Bool ! {Declassify} {
    held.verify(attempt)
}

fn main(root: Root) ! {Net, Read, Write} {
    let out = root.console()
    // Minting a capability is PURE — deriving the handle performs no effect. Using it
    // does. That is why `main` declares Read, Write, and Net but this block alone
    // would need no row at all.
    let reader = root.fs_read("./config")
    let writer = root.fs_write("./out")
    let client = root.http(["example.com"])
    // A PATH IS RELATIVE TO THE CAPABILITY, not to the working directory: `reader` is rooted at
    // `./config`, so the file it reads is named `app.txt`. Writing `"./config/app.txt"` here would
    // look for `./config/config/app.txt` and take the `Err` branch with no diagnostic — this
    // example did exactly that until 2026-09-18, and printed "no config" forever (NE-03). The rule
    // is the attenuation working: a capability cannot name anything outside its own scope.
    match read_config(reader, "app.txt") {
        Ok(text) => out.println("config: " + text)
        Err(e) => out.println("no config")
    }
    match save(writer, "log.txt", "started") {
        Ok(u) => out.println("wrote log")
        Err(e) => out.println("could not write")
    }
    match fetch(client, "https://example.com/health") {
        Ok(body) => out.println("fetched " + str(body.len()) + " bytes")
        Err(e) => out.println("fetch failed")
    }
}

module guide.actors

// An actor owns its state. Nothing outside can reach in: a reference to an actor is
// `tag`, which lets you send to it and read nothing at all. That is what makes data
// races impossible rather than merely discouraged.
actor Worker {
    var done: Int
    var id: Int

    new(worker_id: Int) {
        self.id = worker_id
        self.done = 0
    }

    // `be` declares a BEHAVIOR: an asynchronous message handler. It has no return type
    // — a send yields `Unit` immediately at the call site, and the work happens later.
    be job(n: Int) {
        self.done = self.done + n
    }

    // A plain `fn` inside an actor is a synchronous private helper.
    fn total() -> Int {
        self.done
    }
}

actor Supervisor {
    var dispatched: Int

    new() {
        self.dispatched = 0
    }

    // THE RULE THAT IS EASY TO MISS: sending to another actor is an EFFECT. A behavior
    // that sends must declare `! {Async}`, exactly like any other effect in any other
    // function. Leave it off and this is DL0501 — the row did not admit what the body
    // does. Concurrency is not a separate, parallel system here; it rides the same
    // effect rows as everything else (constitution invariant 12).
    be dispatch(w: tag Worker, n: Int) ! {Async} {
        self.dispatched = self.dispatched + 1
        w.job(n)
    }
}

fn main(root: Root) ! {Async} {
    let sup = spawn Supervisor()
    var i = 0
    while i < 4 {
        let w = spawn Worker(i)
        sup.dispatch(w, i * 10)
        i = i + 1
    }
}

module demo

// Pure: omitted row means !{}. The checker PROVES fib performs no effect.
fn fib(n: Int) -> Int {
    if n < 2 { n } else { fib(n - 1) + fib(n - 2) }
}

// Effectful: the row declares Write; the Cap[Console] param is the permission.
fn greet(out: Cap[Console], name: Str) ! {Write} {
    out.println("hello, " + name)
}

// Higher-order with row polymorphism: apply's row is exactly f's row.
fn apply[T, U, e](f: fn(T) -> U ! e, x: T) -> U ! e {
    f(x)
}

// `?` is demonstrated where it is well-typed: in a Result-returning function whose
// error type matches read_text's. It propagates the IoErr without a match.
fn read_config(fs: Cap[FsRead]) -> Result[Str, IoErr] ! {Read} {
    let text = fs.read_text("app.txt")?
    Ok(text)
}

fn main(root: Root) ! {Read, Write} {
    let out = root.console()
    greet(out, "delulu world")
    out.println("fib(10) = " + str(fib(10)))
    // Row polymorphism, concretely: apply with a pure lambda stays pure here.
    let doubled = apply(fn(x: Int) -> Int { x * 2 }, 21)
    out.println("apply = " + str(doubled))
    let fs = root.fs_read("./config")  // attenuated: read-only, this subtree
    match read_config(fs) {
        Ok(text) => out.println(text)
        Err(_) => out.println("(no config found)")
    }
    let key = root.secret("API_KEY")  // Secret[Str]
    // out.println(key)                         // DL0602: Secret[Str] is not Str
    // out.println(str(key))                    // DL0604: opaque type cannot be stringified
}

module hello

// A minimal program the WASM backend can compile end to end: it derives a console capability
// from root and writes a line. Run it on either engine:
//   delulu run examples/hello_wasm.delulu --grant console
//   delulu run examples/hello_wasm.delulu --engine wasm --grant console
fn main(root: Root) ! {Write} {
    let out = root.console()
    out.println("hello from the wasm engine")
}

// Stage 4 phase 4f flagship demo (spec §5, acceptance criterion 2): "inherit the AI ecosystem".
// DeluluLang imports NumPy, builds a list, calls `mean`, converts the result back to a Float, and
// prints it — the embedded-CPython claim, running behind the honest capability fence.
//
//   delulu run examples/numpy_mean.delulu --grant console \
//       --grant foreign.python=numpy --grant "foreign.python=numpy.*"
//
// The import allowlist gates the INTERFACE (what the program may reach for by name), NOT what NumPy
// transitively imports or does once running — embedded Python has full process authority. Real
// containment is Stage 5 (see `delulu explain DL1305`). The word "sandbox" does not apply here.
module numpy_mean

// The Python work lives in one function whose error channel is `PyErr`. `?` propagates a Python
// exception (or an off-allowlist import, DL1305) as an `Err(PyErr)`. `mean_of` never names `Root`:
// it holds only the `Cap[Python]` handle it was given — reachability threaded in the types.
fn mean_of(py: Cap[Python]) -> Result[Float, PyErr] ! {ForeignCall} {
    let np = py.import("numpy")?
    let xs = py.list([py.of_float(1.0), py.of_float(2.0), py.of_float(3.0), py.of_float(4.0)])
    let m = np.call_method("mean", [xs])?
    py.to_float(m)
}

fn main(root: Root) ! {ForeignCall, Write} {
    let c = root.console()
    let load = root.foreign_load()
    // `root.python(load)` is pure (deriving the handle is not an effect); a missing interpreter is a
    // `ForeignErr::Unavailable` value here (DL1307), never a crash.
    match root.python(load) {
        Ok(py) => match mean_of(py) { Ok(v) => c.println("mean = " + str(v)), Err(e) => c.println("python error [" + e.kind + "]: " + e.message) }
        Err(_) => c.println("embedded Python is unavailable")
    }
}
